import java.util.concurrent.CountDownLatch;

public class Main {
    public static void main(String[] args) throws InterruptedException {
        CountDownLatch latch = new CountDownLatch(1);

        for (int i = 1; i <= 3; i++) {
            final int id = i;
            new Thread(() -> {
                try {
                    latch.await();
                    System.out.println("Athlete " + id + " started!");
                } catch (InterruptedException e) {}
            }).start();
        }

        Thread.sleep(100);
        System.out.println("Go!");
        latch.countDown();
        Thread.sleep(100); // 等待子线程输出完成
    }
}

import java.util.Scanner;
import java.util.function.*;

class StringUtils {
    static String toUpperCase(String s) {
        return s.toUpperCase();
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String input = sc.nextLine();

        // 1. 静态方法引用
        Function<String, String> staticRef = StringUtils::toUpperCase;
        System.out.println(staticRef.apply(input));

        // 2. 特定类型方法引用
        Function<String, Integer> lenRef = String::length;
        System.out.println(lenRef.apply(input));

        // 3. 构造方法引用
        Function<String, StringBuilder> builderRef = StringBuilder::new;
        StringBuilder sb = builderRef.apply(input);
        System.out.println("Builder: " + sb);

        sc.close();
    }
}

import java.util.Scanner;
import java.util.function.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        // 1. Predicate — 断言
        Predicate<Integer> isEven = x -> x % 2 == 0;
        System.out.println("Is " + n + " even? " + isEven.test(n));

        // 2. Function — 转换
        Function<Integer, String> format = x -> "Number:" + x;
        System.out.println("Formatted: " + format.apply(n));

        // 3. Supplier — 提供默认值
        Supplier<Integer> defaultVal = () -> 42;
        System.out.println("Default: " + defaultVal.get());

        sc.close();
    }
}
